func (r *mutationResolver) SetOperatingHours(ctx context.Context, restaurantID string, hours []*model.SetOperatingHoursInput) ([]*model.OperatingHours, error) {
	if _, err := utils.RequireRestaurantStaff(ctx, r.Resolver.DB, restaurantID, false); err != nil {
		return nil, nil
	}

	tx, err := r.Resolver.DB.Begin(ctx)
	if err != nil {
		log.Printf("🔴 FAILED TO ACQUIRE TRANSACTION IN SETOPERATINGHOURS: %v", err)
		return nil, fmt.Errorf("internal server error")
	}
	defer tx.Rollback(ctx)

	var results []*model.OperatingHours
	for _, h := range hours {
		isClosed := false
		if h.IsClosed != nil {
			isClosed = *h.IsClosed
		}

		var oh model.OperatingHours
		err := tx.QueryRow(ctx, `
			INSERT INTO operating_hours (restaurant_id, day_of_week, open_time, close_time, is_closed)
			VALUES ($1, $2, $3, $4, $5)
			ON CONFLICT (restaurant_id, day_of_week)
			DO UPDATE SET open_time = $3, close_time = $4, is_closed = $5
			RETURNING id, day_of_week, open_time, close_time, is_closed
		`, restaurantID, h.DayOfWeek, h.OpenTime, h.CloseTime, isClosed).
			Scan(&oh.ID, &oh.DayOfWeek, &oh.OpenTime, &oh.CloseTime, &oh.IsClosed)

		if err != nil {
			log.Printf("🔴 FAILED TO UPSERT OPERATING HOURS FOR DAY %d: %v", h.DayOfWeek, err)
			return nil, fmt.Errorf("internal server error: failed saving operating hours")
		}
		results = append(results, &oh)
	}

	if err := tx.Commit(ctx); err != nil {
		log.Printf("🔴 TRANSACTION COMMIT FAILED IN SETOPERATINGHOURS: %v", err)
		return nil, fmt.Errorf("internal server error")
	}

	return results, nil
}

