// UpdateBooking is the resolver for the updateBooking field.
// UpdateBooking is the resolver for the updateBooking field.
func (r *mutationResolver) UpdateBooking(ctx context.Context, id string, input model.UpdateBookingInput) (*model.Booking, error) {
	// Resolve the owning restaurant first so we can enforce staff access.
	// This also covers cancelBooking and assignTable, which delegate here.
	var restaurantID string
	if err := r.Resolver.DB.QueryRow(ctx,
		`SELECT restaurant_id FROM bookings WHERE id = $1`, id,
	).Scan(&restaurantID); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "not found: booking does not exist",
				Extensions: map[string]any{"code": "NOT_FOUND"},
			})
			return nil, nil
		}
		return nil, err
	}
	if _, err := utils.RequireRestaurantStaff(ctx, r.Resolver.DB, restaurantID, false); err != nil {
		return nil, nil
	}

	var bookingTime *time.Time
	var timeRange *string

	if input.BookingTime != nil {
		parsed, err := time.Parse(time.RFC3339, *input.BookingTime)
		if err != nil {
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "invalid bookingTime: must be ISO 8601 / RFC3339",
				Extensions: map[string]any{"code": "BAD_USER_INPUT"},
			})
			return nil, nil
		}
		bookingTime = &parsed

		// booking_time changed — time_range must be recalculated to match,
		// or the EXCLUDE constraint checks a stale window. Duration doesn't
		// change here, so pull the current duration_minutes to compute the
		// new end time.
		var durationMinutes int
		if err := r.Resolver.DB.QueryRow(ctx,
			`SELECT duration_minutes FROM bookings WHERE id = $1`, id,
		).Scan(&durationMinutes); err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				graphql.AddError(ctx, &gqlerror.Error{
					Message:    "not found: booking does not exist",
					Extensions: map[string]any{"code": "NOT_FOUND"},
				})
				return nil, nil
			}
			return nil, err
		}

		end := parsed.Add(time.Duration(durationMinutes) * time.Minute)
		tr := fmt.Sprintf("[%s,%s)", parsed.Format(time.RFC3339), end.Format(time.RFC3339))
		timeRange = &tr
	}

	query := `
		UPDATE bookings SET
			table_id = COALESCE($1, table_id),
			party_size = COALESCE($2, party_size),
			booking_time = COALESCE($3, booking_time),
			time_range = COALESCE($4::tstzrange, time_range),
			status = COALESCE($5, status),
			special_requests = COALESCE($6, special_requests),
			payment_status = COALESCE($7, payment_status),
			updated_at = NOW()
		WHERE id = $8
		RETURNING id, restaurant_id, customer_id, table_id, party_size, booking_time,
			duration_minutes, status, special_requests, payment_status, source, created_at, updated_at
	`

	var b model.Booking
	var bt, createdAt, updatedAt time.Time
	err := r.Resolver.DB.QueryRow(ctx, query,
		input.TableID, input.PartySize, bookingTime, timeRange, input.Status, input.SpecialRequests, input.PaymentStatus, id,
	).Scan(
		&b.ID, &b.RestaurantID, &b.CustomerID, &b.TableID, &b.PartySize, &bt,
		&b.DurationMinutes, &b.Status, &b.SpecialRequests, &b.PaymentStatus, &b.Source, &createdAt, &updatedAt,
	)

	if err != nil {
		if utils.IsExclusionViolation(err) {
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "that table is already booked for the requested time",
				Extensions: map[string]any{"code": "TABLE_ALREADY_BOOKED"},
			})
			return nil, nil
		}
		if errors.Is(err, pgx.ErrNoRows) {
			graphql.AddError(ctx, &gqlerror.Error{
				Message:    "not found: booking does not exist",
				Extensions: map[string]any{"code": "NOT_FOUND"},
			})
			return nil, nil
		}
		log.Printf("🔴 DATABASE UPDATE FAILED IN UPDATEBOOKING: %v", err)
		graphql.AddError(ctx, &gqlerror.Error{
			Message:    "internal server error: failed saving booking updates",
			Extensions: map[string]any{"code": "INTERNAL_SERVER_ERROR"},
		})
		return nil, nil
	}

	b.BookingTime = bt.Format(time.RFC3339)
	b.CreatedAt = createdAt.Format(time.RFC3339)
	b.UpdatedAt = updatedAt.Format(time.RFC3339)
	return &b, nil
}

